"""TASK 2 -- build PGL(3,8) with our own generators, verify |PGL| = 16,482,816,
and verify that every generator acts by a collineation.

Method
  * |GL(3,8)| is counted by the standard ordered-basis argument
        (8^3-1)(8^3-8)(8^3-8^2) = 511*504*448 = 115,379,712,
    and the 7 scalar matrices act trivially, so |PGL(3,8)| = 115,379,712/7.
  * The order of the group G = <D,T,S,U> generated by the four explicit
    matrices is computed *exactly* in Python by a textbook Schreier-Sims
    orbit-stabiliser recursion: at each level the stabiliser of a base point is
    generated by the Schreier generators (Schreier's lemma), which is an exact
    generating set, so the product of the orbit lengths is exactly |G|.
  * Each generator is checked to be invertible, to induce a permutation of the
    73 points, and to map every one of the 73 lines onto a line.
"""

import sys

import pg2q8 as P


# ---------------------------------------------------------------- generators
def det(A):
    return P.mat_det(A)


def check_generators():
    out = []
    canon = P.canonical_lines()
    for name, A in zip("D T S U".split(), P.GENERATORS):
        d = det(A)
        perm = P.matrix_perm(A)
        # permutation?
        isperm = sorted(perm) == list(range(73))
        # collineation: every canonical line is mapped onto a canonical line
        ok = True
        for L in canon:
            im = frozenset(perm[p] for p in L)
            if im not in canon:
                ok = False
                break
        out.append(
            f"gen_{name}: {P.mat_str(A)}  det={P.gf8_name(d) if d else '0'} "
            f"invertible={d != 0} permutation={isperm} collineation={ok}"
        )
    return out


# ---------------------------------------------------------------- order
IDENT = tuple(range(73))


def compose(a, b):
    """(a o b)[i] = a[b[i]]"""
    return tuple(a[b[i]] for i in range(73))


def inverse(a):
    r = [0] * 73
    for i, x in enumerate(a):
        r[x] = i
    return tuple(r)


def schreier_sims_order(gens, verbose=True, max_gens=200000):
    """Exact order by the orbit-stabiliser recursion with Schreier generators."""

    def rec(gens, level):
        gens = [g for g in gens if g != IDENT]
        if not gens:
            return 1, []
        # base point: first moved point
        b = None
        for g in gens:
            for i in range(73):
                if g[i] != i:
                    b = i
                    break
            if b is not None:
                break
        # orbit + transversal (Schreier tree)
        trans = {b: IDENT}
        queue = [b]
        qi = 0
        while qi < len(queue):
            x = queue[qi]
            qi += 1
            t = trans[x]
            for g in gens:
                y = g[x]
                if y not in trans:
                    trans[y] = compose(g, t)  # maps b -> y
                    queue.append(y)
        orbit_len = len(trans)
        # Schreier generators of the stabiliser of b
        stab = []
        seen = set()
        inv_trans = {y: inverse(t) for y, t in trans.items()}
        for x, t in trans.items():
            for g in gens:
                y = g[x]
                u = compose(inv_trans[y], compose(g, t))  # fixes b
                if u != IDENT and u not in seen:
                    seen.add(u)
                    if len(stab) > max_gens:
                        raise RuntimeError("Schreier generator explosion")
                    stab.append(u)
        if verbose:
            print(f"  level {level}: base point {b:2d}, orbit {orbit_len:3d}, "
                  f"{len(gens):6d} gens -> {len(stab):6d} stabiliser gens")
        sub, chain = rec(stab, level + 1)
        return orbit_len * sub, [(b, orbit_len, len(gens), len(stab))] + chain

    return rec(list(gens), 1)


def scalar_matrices_act_trivially():
    """The 7 scalar matrices of GL(3,8) act as the identity on the points."""
    for lam in range(1, 8):
        A = ((lam, 0, 0), (0, lam, 0), (0, 0, lam))
        perm = P.matrix_perm(A)
        if perm != tuple(range(73)):
            return False
    return True


def main():
    out = []

    def say(s=""):
        out.append(str(s))
        print(s)

    say("== generators ==")
    for line in check_generators():
        say(line)

    say()
    say("== |GL(3,8)| and |PGL(3,8)| by counting ==")
    q = 8
    n1 = q ** 3 - 1              # non-zero first column
    n2 = q ** 3 - q              # second column outside span of first
    n3 = q ** 3 - q ** 2         # third column outside span of the first two
    gl = n1 * n2 * n3
    say(f"ordered bases: {n1} * {n2} * {n3} = {gl}")
    say(f"scalar matrices act trivially on points: {scalar_matrices_act_trivially()}")
    say(f"|PGL(3,8)| = |GL(3,8)| / 7 = {gl // 7}")
    say(f"target from the claim: 16482816   match: {gl // 7 == 16482816}")

    say()
    say("== |<D,T,S,U>| by Schreier-Sims ==")
    order, chain = schreier_sims_order([tuple(p) for p in
                                        (P.matrix_perm(A) for A in P.GENERATORS)])
    say(f"computed order = {order}")
    say(f"orbit lengths of the stabiliser chain: {[c[1] for c in chain]}")
    say(f"base points: {[c[0] for c in chain]}")
    say(f"ORDER MATCH 16482816: {order == 16482816}")
    say(f"generators generate all of PGL(3,8): {order == gl // 7}")

    ok = order == gl // 7 == 16482816
    say()
    say(f"TASK 2: {'PASS' if ok else 'FAIL'}")

    with open("results_task2.txt", "w", encoding="utf-8") as fh:
        fh.write("\n".join(out) + "\n")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
